import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Send Mail (Gmail)","description":"","frontmatter":{"prev":{"text":"Gmail API Search Queries","link":"/documentation/field-types/google-service-gmail/gmail-api-search-queries"},"next":{"text":"Fetch Google Sheet Data","link":"/documentation/field-types/google-service-sheet/fetch-google-sheet-data"}},"headers":[],"relativePath":"documentation/field-types/google-service-gmail/send-mail-gmail.md","filePath":"documentation/field-types/google-service-gmail/send-mail-gmail.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/google-service-gmail/send-mail-gmail.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="send-mail-gmail" tabindex="-1">Send Mail (Gmail) <a class="header-anchor" href="#send-mail-gmail" aria-label="Permalink to “Send Mail (Gmail)”">​</a></h1><p>Send automated emails programmatically through Gmail with support for HTML templates, dynamic spreadsheet variables, file attachments, and multiple recipients.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The <strong>Send Mail (Gmail)</strong> field type enables automated outbound email communication directly from form routines. Whether dispatching confirmation receipts, notifying team members of form completion, or emailing generated <code>.xlsx</code> reports and PDF files, this field leverages the Google Gmail API to deliver messages securely.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Google Service Account</strong></td><td>Dropdown</td><td>Logged-in Google account used as the sender.</td><td>Yes</td></tr><tr><td><strong>To</strong></td><td>Input Tags</td><td>Comma-separated list of recipient email addresses.</td><td>Yes</td></tr><tr><td><strong>Subject</strong></td><td>Text Input</td><td>Email subject line (supports dynamic variables).</td><td>Yes</td></tr><tr><td><strong>Enable Attachments</strong></td><td>Toggle Switch</td><td>Enables sending one or more file attachments.</td><td>No</td></tr><tr><td><strong>Attachments URL/Path</strong></td><td>Text Input</td><td>Local file paths or URLs to attach (comma-separated).</td><td>When attachments enabled</td></tr><tr><td><strong>Enable Custom File Names</strong></td><td>Toggle Switch</td><td>Overrides raw attachment filenames with custom labels.</td><td>No</td></tr><tr><td><strong>Attachments File Name</strong></td><td>Text Input</td><td>Custom file names for attachments (comma-separated).</td><td>When custom names enabled</td></tr><tr><td><strong>Attachments File MIME Type</strong></td><td>Text Input</td><td>Explicit MIME types for attached files.</td><td>When custom names enabled</td></tr><tr><td><strong>Enable Retry on Failure</strong></td><td>Toggle Switch</td><td>Re-attempts sending if API connection errors occur.</td><td>No</td></tr><tr><td><strong>Max Retries</strong></td><td>Number Input</td><td>Maximum number of send retry attempts.</td><td>When retry enabled</td></tr><tr><td><strong>Email Body</strong></td><td>Default Value</td><td>Message content (supports plain text, HTML, and dynamic variables).</td><td>Yes</td></tr></tbody></table><hr><h2 id="option-details" tabindex="-1">Detailed Configuration Breakdown <a class="header-anchor" href="#option-details" aria-label="Permalink to “Detailed Configuration Breakdown”">​</a></h2><h3 id="google-service-account" tabindex="-1">Google Service Account <a class="header-anchor" href="#google-service-account" aria-label="Permalink to “Google Service Account”">​</a></h3><p>Select your authorized account from <a href="/documentation/services/google-service.html">Google Service</a>. Outbound emails are sent from this address.</p><h3 id="recipient-addresses-to" tabindex="-1">Recipient Addresses (<code>To</code>) <a class="header-anchor" href="#recipient-addresses-to" aria-label="Permalink to “Recipient Addresses (To)”">​</a></h3><p>Specify destination addresses separated by commas:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>client@example.com, manager@company.com</span></span></code></pre></div><p>You can also inject spreadsheet column values:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{$CustomerEmail$}</span></span></code></pre></div><h3 id="subject-line" tabindex="-1">Subject Line <a class="header-anchor" href="#subject-line" aria-label="Permalink to “Subject Line”">​</a></h3><p>Define the message subject, which can incorporate dynamic row data:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Order Confirmation - #{$OrderID$} for {$CustomerName$}</span></span></code></pre></div><h3 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to “Attachments”">​</a></h3><ul><li><strong>Attachments URL/Path</strong>: Provide local paths (e.g., <code>C:\\Reports\\Invoice.pdf</code>) or web URLs.</li><li><strong>Custom File Names</strong>: Rename generated exports (e.g., <code>Billing_Report_{$Date$}.xlsx</code>) before dispatch.</li></ul><h3 id="email-body-templating" tabindex="-1">Email Body Templating <a class="header-anchor" href="#email-body-templating" aria-label="Permalink to “Email Body Templating”">​</a></h3><p>The email body supports HTML markup for branded formatting:</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Hello &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{$Name$}&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Your application for &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">em</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{$Service$}&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">em</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; was processed successfully.&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">br</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Confirmation Reference: &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{$RefNumber$}&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-customer-submission-confirmation" tabindex="-1">Example 1: Customer Submission Confirmation <a class="header-anchor" href="#example-1-customer-submission-confirmation" aria-label="Permalink to “Example 1: Customer Submission Confirmation”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: support@mybusiness.com</span></span>
<span class="line"><span>To: {$Email$}</span></span>
<span class="line"><span>Subject: Submission Received - Ref: {$ReferenceID$}</span></span>
<span class="line"><span>Email Body:</span></span>
<span class="line"><span>Thank you {$FullName$}, we have received your form details.</span></span>
<span class="line"><span>Your reference code is {$ReferenceID$}.</span></span></code></pre></div><h3 id="example-2-dispatching-exported-report-attachment" tabindex="-1">Example 2: Dispatching Exported Report Attachment <a class="header-anchor" href="#example-2-dispatching-exported-report-attachment" aria-label="Permalink to “Example 2: Dispatching Exported Report Attachment”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: automated@mybusiness.com</span></span>
<span class="line"><span>To: audit@company.com</span></span>
<span class="line"><span>Subject: Daily Automation Report - {$CurrentDate$}</span></span>
<span class="line"><span>Enable Attachments: ON</span></span>
<span class="line"><span>Attachments URL/Path: D:\\Reports\\Daily_Export.xlsx</span></span>
<span class="line"><span>Enable Custom File Names: ON</span></span>
<span class="line"><span>Attachments File Name: Daily_Export_{$CurrentDate$}.xlsx</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><h3 id="do-s" tabindex="-1">Do&#39;s <a class="header-anchor" href="#do-s" aria-label="Permalink to “Do&#39;s”">​</a></h3><ul><li><strong>Use Column Variables</strong>: Dynamically personalize messages using spreadsheet tags like <code>{$CustomerName$}</code> and <code>{$Email$}</code>.</li><li><strong>Verify Attachment Paths</strong>: Ensure local file paths exist before triggering execution.</li><li><strong>Enable Retries on Network Dependencies</strong>: Turn ON <strong>Enable Retry on Failure</strong> for resilient unattended workflows.</li></ul><h3 id="don-ts" tabindex="-1">Don&#39;ts <a class="header-anchor" href="#don-ts" aria-label="Permalink to “Don&#39;ts”">​</a></h3><ul><li><strong>Do Not Send Unvalidated Emails</strong>: Test email templates with your own email before running large batch workflows.</li><li><strong>Do Not Exceed Gmail API Quotas</strong>: Adhere to standard Google Workspace daily sending quotas.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Sending fails with 403 Forbidden</strong></td><td>Gmail API send scope not granted</td><td>Re-authenticate your Google account under <a href="/documentation/services/google-service.html">Google Service</a>.</td></tr><tr><td><strong>Attachment missing in delivered email</strong></td><td>Local file path invalid or file locked</td><td>Verify the absolute file path on disk.</td></tr><tr><td><strong>HTML tags visible as plain text</strong></td><td>Raw unescaped brackets in plain text mode</td><td>Ensure body is formatted with standard semantic HTML tags.</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/chat.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/fetch-mail-gmail.html">Fetch Mail (Gmail)</a></li><li><img src="/svg/globe.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/gmail-api-search-queries.html">Gmail API Search Queries</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/services/google-service.html">Google Service Account Setup</a></li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template (.xlsx)</a></li></ul>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};